 // sum up the absolutes\n    float aSum = fabs(aX) + fabs(aY) + fabs(aZ);\n\n    // check if it's above the threshold\n    if (aSum >= accelerationThreshold) {\n      // reset the sample read count\n      samplesRead = 0;\n      break;\n    }\n  }\n\n  // check if the all the required samples have been read since\n  // the last time the significant motion was detected\n  while (samplesRead < numSamples) {\n    // check if both new acceleration and gyroscope data is\n    // available\n    // read the acceleration and gyroscope data\n\n    samplesRead++;\n\n    // print the data in CSV format\n    Serial.print(myIMU.readFloatAccelX(), 3);\n    Serial.print(',');\n    Serial.print(myIMU.readFloatAccelY(), 3);\n    Serial.print(',');\n    Serial.print(myIMU.readFloatAccelZ(), 3);\n    Serial.print(',');\n    Serial.print(myIMU.readFloatGyroX(), 3);\n    Serial.print(',');\n    Serial.print(myIMU.readFloatGyroY(), 3);\n    Serial.print(',');\n    Serial.print(myIMU.readFloatGyroZ(), 3);\n    Serial.println();\n\n    if (samplesRead == numSamples) {\n      // add an empty line if it's the last sample\n      Serial.println();\n    }\n  }\n}\n"})}),"\n",(0,s.jsx)(n.admonition,{type:"tip",children:(0,s.jsx)(n.p,{children:"Devido \xe0 atualiza\xe7\xe3o da biblioteca LSM6DS3, se voc\xea j\xe1 adicionou essa biblioteca anteriormente ao usu\xe1rio, ser\xe1 necess\xe1rio baixar novamente a vers\xe3o 2.0.4 ou superior e adicionar o arquivo ZIP ao Arduino."})}),"\n",(0,s.jsx)(n.h3,{id:"vis\xe3o-geral-das-fun\xe7\xf5es",children:"Vis\xe3o geral das fun\xe7\xf5es"}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.strong,{children:"Incluir Bibliotecas"})}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-cpp",children:"  #include <LSM6DS3.h> \n  #include <Wire.h>\n"})}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsx)(n.li,{children:"Inclui a biblioteca para comunica\xe7\xe3o com o sensor LSM6DS3."}),"\n",(0,s